class SweepConfigPayload(BaseModel):
    destination_iban: str
    sweep_percentage: float

@router.put("/api/v1/payout-sweeps/schedules/{schedule_id}/destination")
def update_sweep_destination(
    schedule_id: int,
    payload: SweepConfigPayload,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user)
):
    sweep = db.query(RecurringSweepSchedule).filter(
        RecurringSweepSchedule.id == schedule_id,
        RecurringSweepSchedule.merchant_id == current_user.merchant_id
    ).first()
    if not sweep:
        raise HTTPException(status_code=404, detail="Sweep schedule not found or access denied")
    sweep.destination_iban = payload.destination_iban
    sweep.percentage = payload.sweep_percentage
    db.commit()
    return {"status": "updated", "schedule_id": schedule_id}
